tests:
def test_passed_report():
    assert format_test_report("test_login", True, 120) == "[PASSED] test_login (120 ms)", "неверный формат для успешного теста"


def test_failed_report():
    assert format_test_report("test_logout", False, 95) == "[FAILED] test_logout (95 ms)", "неверный формат для упавшего теста"


def test_default_duration():
    assert format_test_report("test_registration", False) == "[FAILED] test_registration (0 ms)", "duration_ms по умолчанию должен быть равен 0"


def test_keyword_arguments():
    result = format_test_report(test_name="test_profile", passed=True, duration_ms=50)
    assert result == "[PASSED] test_profile (50 ms)", "функция должна корректно работать с именованными аргументами"
